 SELECT coalesce(a.identity,e.identity) AS "CHECK",
 CASE WHEN a.identity IS NULL THEN 'ausente' WHEN e.identity IS NULL THEN 'objeto adicional' WHEN a.detail IS DISTINCT FROM e.detail THEN 'contrato divergente' ELSE 'contrato conferido' END AS "RESULTADO",
 CASE WHEN coalesce(a.identity,e.identity) ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))' THEN 'ATENÇÃO'
 WHEN a.detail IS DISTINCT FROM e.detail THEN 'BLOQUEIO' ELSE 'OK' END AS "STATUS"
 FROM actual a FULL JOIN expected e USING(identity) ORDER BY 1) report WHERE "STATUS"='BLOQUEIO') THEN
 RAISE EXCEPTION '024 baseline contract drift: rerun read-only preflight and review; no overwrite';
 END IF;
END $contract$;
-- END GENERATED 024 BASELINE ASSERTION

-- Accept only compact or exactly masked ASCII forms, with surrounding ASCII spaces.
-- translate uppercases without locale-dependent Unicode transformations; never strip letters.
CREATE FUNCTION engmarq_private.cnpj_canonico(raw text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path='' AS $$
 SELECT CASE WHEN btrim(raw) COLLATE "C" ~ '^([0-9A-Za-z]{12}[0-9]{2}|[0-9A-Za-z]{2}\.[0-9A-Za-z]{3}\.[0-9A-Za-z]{3}/[0-9A-Za-z]{4}-[0-9]{2})$'
 THEN translate(btrim(raw),'abcdefghijklmnopqrstuvwxyz./-','ABCDEFGHIJKLMNOPQRSTUVWXYZ') END
$$;
CREATE FUNCTION engmarq_private.cnpj_valido(raw text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE c text := engmarq_private.cnpj_canonico(raw); total integer; dv integer; j integer;
 weights integer[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
BEGIN
 IF c IS NULL OR c=repeat(substr(c,1,1),14) THEN RETURN false; END IF;
 total:=0;
 FOR j IN 1..12 LOOP total:=total+(ascii(substr(c,j,1))-48)*weights[j]; END LOOP;
 dv:=total%11; dv:=CASE WHEN dv<2 THEN 0 ELSE 11-dv END;
 IF substr(c,13,1)<>dv::text THEN RETURN false; END IF;
 total:=0; weights:=ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
 FOR j IN 1..13 LOOP total:=total+(ascii(substr(c,j,1))-48)*weights[j]; END LOOP;
 dv:=total%11; dv:=CASE WHEN dv<2 THEN 0 ELSE 11-dv END;
 RETURN substr(c,14,1)=dv::text;
END $$;
REVOKE ALL ON FUNCTION engmarq_private.cnpj_canonico(text),engmarq_private.cnpj_valido(text) FROM PUBLIC,anon,authenticated;
-- Required for generated columns/CHECK during existing authenticated company writes.
GRANT EXECUTE ON FUNCTION engmarq_private.cnpj_canonico(text),engmarq_private.cnpj_valido(text) TO authenticated,service_role;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.empresas WHERE NOT engmarq_private.cnpj_valido(cnpj))
 OR EXISTS(SELECT 1 FROM public.empresas GROUP BY engmarq_private.cnpj_canonico(cnpj) HAVING count(*)>1) THEN
  RAISE EXCEPTION '024 blocked: invalid/unexpected CNPJ or canonical collision; no automatic repair' USING ERRCODE='23514';
 END IF;
END $$;
ALTER TABLE public.empresas
 ADD COLUMN cnpj_canonico text GENERATED ALWAYS AS (engmarq_private.cnpj_canonico(cnpj)) STORED,
 ADD CONSTRAINT empresas_cnpj_valido_check CHECK(engmarq_private.cnpj_valido(cnpj)),
 ADD CONSTRAINT empresas_cnpj_canonico_key UNIQUE(cnpj_canonico),
 ADD COLUMN cep text,
 ADD COLUMN logradouro text,
 ADD COLUMN numero text,
 ADD COLUMN complemento text,
 ADD COLUMN bairro text;
COMMENT ON COLUMN public.empresas.cnpj_canonico IS 'Derived identity, numeric or alphanumeric; original cnpj preserved';
GRANT INSERT(cep,logradouro,numero,complemento,bairro),UPDATE(cep,logradouro,numero,complemento,bairro)
 ON public.empresas TO authenticated;

-- Preserve 021 authorization and logo contract. Extend only its editable address list.
-- CNPJ correction is deliberately infrastructure-only until an audited correction workflow exists.
CREATE OR REPLACE FUNCTION engmarq_private.guard_empresa_write()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor record;
 editable text[] := ARRAY['razao_social','setor','cidade','uf','responsavel','email','telefone','logo_url',
   'cep','logradouro','numero','complemento','bairro'];
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RETURN NEW; END IF;
 SELECT p.role,p.active,p.empresa_id INTO actor FROM public.user_profiles p WHERE p.id=auth.uid() FOR SHARE;
 IF NOT FOUND OR NOT actor.active THEN RAISE EXCEPTION 'Company write denied' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
   RAISE EXCEPTION 'Immutable company fields' USING ERRCODE='42501';
  END IF;
  IF NEW.cnpj IS DISTINCT FROM OLD.cnpj THEN
   RAISE EXCEPTION 'CNPJ correction requires a controlled infrastructure workflow' USING ERRCODE='42501';
  END IF;
  IF actor.role<>'admin' AND (actor.role NOT IN ('empresa','gestor') OR OLD.id<>actor.empresa_id
   OR OLD.status<>'ativa' OR (to_jsonb(NEW)-editable-ARRAY['cnpj_canonico']) IS DISTINCT FROM
   (to_jsonb(OLD)-editable-ARRAY['cnpj_canonico'])) THEN
   RAISE EXCEPTION 'Administrative company fields denied' USING ERRCODE='42501';
  END IF;
 ELSIF actor.role<>'admin' THEN
  RAISE EXCEPTION 'Only platform admin may create companies' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION engmarq_private.guard_empresa_write() FROM PUBLIC,anon,authenticated;

CREATE TABLE public.features (
 feature_key text PRIMARY KEY CHECK(feature_key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$'),
 descricao text NOT NULL CHECK(length(descricao) BETWEEN 1 AND 500)
);
INSERT INTO public.features(feature_key,descricao) VALUES
 ('empresa.cadastro','Cadastro empresarial próprio, incluindo logo'),
 ('usuarios.gestao','Gestão de usuários do próprio tenant'),
 ('colaboradores.gestao','Colaboradores e catálogos organizacionais necessários'),
 ('treinamentos','Treinamentos, matriz e certificados'),
 ('exames','Exames e ASOs'),('documentos','Documentos não-ASO'),
 ('epi','Fichas EPI e assinaturas'),('relatorios.sst','Relatórios SST');
CREATE TABLE public.empresa_comercial (
 empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),
 origem text NOT NULL CHECK(origem IN ('autocadastro','administrativo','legado')),
 -- Opaque optional future commercial reference; no plan resolver or implicit authorization.
 plano_comercial_id uuid,
 titularidade text CHECK(titularidade IN ('autodeclarado','verificado')),
 verificado_por uuid REFERENCES public.user_profiles(id),
 verificado_em timestamptz,
 CONSTRAINT empresa_comercial_verificacao_check CHECK(
  (titularidade='verificado' AND verificado_por IS NOT NULL AND verificado_em IS NOT NULL)
  OR (titularidade IS DISTINCT FROM 'verificado' AND verificado_por IS NULL AND verificado_em IS NULL))
);
CREATE TABLE public.empresa_features (
 empresa_id uuid NOT NULL REFERENCES public.empresas(id),
 feature_key text NOT NULL REFERENCES public.features(feature_key),
 enabled boolean NOT NULL,
 PRIMARY KEY(empresa_id,feature_key)
);
CREATE TABLE public.empresa_limites (
 empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),
 -- No DEFAULT: NULL (unlimited) or a positive limit must be explicit.
 max_colaboradores_ativos integer CHECK(max_colaboradores_ativos>0),
 ilimitado boolean NOT NULL DEFAULT false,
 CHECK((ilimitado AND max_colaboradores_ativos IS NULL)
  OR (NOT ilimitado AND max_colaboradores_ativos IS NOT NULL))
);
CREATE TABLE public.empresa_uso (
 empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),
 colaboradores_ativos bigint NOT NULL CHECK(colaboradores_ativos>=0),
 apurado_em timestamptz NOT NULL,
 CONSTRAINT empresa_uso_no_future_check CHECK(isfinite(apurado_em))
);
COMMENT ON TABLE public.empresa_uso IS 'Protected aggregate infrastructure. No backfill or live maintenance in 024; quota enforcement belongs to 025';
CREATE TABLE public.empresa_diagnostico_sst (
 empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),
 possui_pgr text CHECK(possui_pgr IN ('sim','nao','nao_sei')),
 possui_pcmso text CHECK(possui_pcmso IN ('sim','nao','nao_sei')),
 possui_treinamentos text CHECK(possui_treinamentos IN ('sim','nao','nao_sei')),
 programas_documentos_em_dia text CHECK(programas_documentos_em_dia IN ('sim','nao','nao_sei')),
 treinamentos_em_dia text CHECK(treinamentos_em_dia IN ('sim','nao','nao_sei')),
 quantidade_aproximada_colaboradores integer CHECK(quantidade_aproximada_colaboradores>=0),
 conhece_grau_risco boolean,
 grau_risco_informado smallint,
 schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version=1),
 informado_por uuid NOT NULL REFERENCES public.user_profiles(id),
 informado_em timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(informado_em)),
 CONSTRAINT empresa_diagnostico_grau_check CHECK(
  (conhece_grau_risco IS TRUE AND grau_risco_informado IS NOT NULL AND grau_risco_informado BETWEEN 1 AND 4)
  OR (conhece_grau_risco IS NOT TRUE AND grau_risco_informado IS NULL))
);
COMMENT ON TABLE public.empresa_diagnostico_sst IS 'Autodeclared initial SST diagnosis, not compliance or official PGR/PCMSO evidence';
CREATE TABLE public.auditoria_comercial (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 empresa_id uuid NOT NULL REFERENCES public.empresas(id),
 objeto text NOT NULL CHECK(objeto IN ('empresa_comercial','empresa_features','empresa_limites','empresa_status')),
 operacao text NOT NULL CHECK(operacao IN ('INSERT','UPDATE','DELETE')),
 feature_key text,
 anterior jsonb,
 novo jsonb,
 ator_id uuid REFERENCES auth.users(id),
 executor text NOT NULL,
 registrado_em timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX auditoria_comercial_empresa_data_idx ON public.auditoria_comercial(empresa_id,registrado_em);
CREATE TABLE engmarq_private.onboarding_solicitacoes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 auth_user_id uuid NOT NULL REFERENCES auth.users(id),
 chave_idempotencia uuid NOT NULL,
 payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),
 estado text NOT NULL CHECK(estado IN ('pending_email','onboarding','completed','expired','failed_retryable')),
 empresa_id uuid REFERENCES public.empresas(id),
 criado_em timestamptz NOT NULL DEFAULT clock_timestamp(),
 expira_em timestamptz NOT NULL CHECK(isfinite(expira_em)),
 UNIQUE(auth_user_id,chave_idempotencia),
 CHECK(expira_em>criado_em),
 CHECK((estado='completed' AND empresa_id IS NOT NULL) OR (estado<>'completed' AND empresa_id IS NULL))
);
CREATE UNIQUE INDEX onboarding_um_resultado_por_usuario ON engmarq_private.onboarding_solicitacoes(auth_user_id) WHERE estado='completed';
COMMENT ON TABLE engmarq_private.onboarding_solicitacoes IS 'Persistence only; no payload/password, bootstrap function, endpoint or client provision grant in 024';

CREATE FUNCTION engmarq_private.is_commercial_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT current_setting('role',true)='authenticated' AND EXISTS(
  SELECT 1 FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
  WHERE p.id=auth.uid() AND p.active AND p.role='admin' AND e.status='ativa')
$$;
CREATE FUNCTION engmarq_private.can_read_foundation(company uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT engmarq_private.is_commercial_admin() OR (current_setting('role',true)='authenticated' AND EXISTS(
  SELECT 1 FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
  WHERE p.id=auth.uid() AND p.active AND p.empresa_id=company AND e.status='ativa'
  AND p.role IN ('empresa','gestor','operacional')))
$$;
CREATE FUNCTION engmarq_private.has_empresa_feature(company uuid, key text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 -- Entitlement lookup scoped to an active tenant identity, never an Admin operational capability.
 SELECT current_setting('role',true)='authenticated' AND EXISTS(
  SELECT 1 FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
  JOIN public.empresa_features f ON f.empresa_id=p.empresa_id
  JOIN public.features catalog ON catalog.feature_key=f.feature_key
  WHERE p.id=auth.uid() AND p.active AND e.status='ativa' AND p.empresa_id=company
   AND p.role IN ('empresa','gestor','operacional') AND f.feature_key=key AND f.enabled)
$$;
REVOKE ALL ON FUNCTION engmarq_private.is_commercial_admin(),engmarq_private.can_read_foundation(uuid),
 engmarq_private.has_empresa_feature(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION engmarq_private.is_commercial_admin(),engmarq_private.can_read_foundation(uuid),
 engmarq_private.has_empresa_feature(uuid,text) TO authenticated;

CREATE FUNCTION engmarq_private.guard_commercial_write() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor record; real_use bigint; stored_use bigint;
BEGIN
 IF TG_OP='UPDATE' AND NEW.empresa_id IS DISTINCT FROM OLD.empresa_id THEN
  RAISE EXCEPTION 'Immutable commercial tenant' USING ERRCODE='42501';
 END IF;
 IF current_setting('role',true)='authenticated' THEN
  SELECT p.role,p.active,e.status INTO actor FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
   WHERE p.id=auth.uid() FOR SHARE OF p,e;
  IF NOT FOUND OR NOT actor.active OR actor.role<>'admin' OR actor.status<>'ativa' THEN
   RAISE EXCEPTION 'Commercial write denied' USING ERRCODE='42501';
  END IF;
 END IF;
 IF TG_TABLE_NAME='empresa_comercial' THEN
  IF TG_OP='UPDATE' AND NEW.origem IS DISTINCT FROM OLD.origem THEN
   RAISE EXCEPTION 'Commercial origin is immutable' USING ERRCODE='42501';
  END IF;
 END IF;
 IF TG_TABLE_NAME='empresa_limites' THEN
  -- 016 employee guard takes SHARE on this company, serializing current authenticated inserts/deactivations.
  -- 025 must share a quota lock protocol, including technical employee writes.
  PERFORM 1 FROM public.empresas WHERE id=NEW.empresa_id FOR UPDATE;
  SELECT count(*) INTO real_use FROM public.colaboradores WHERE empresa_id=NEW.empresa_id AND active;
  SELECT colaboradores_ativos INTO stored_use FROM public.empresa_uso WHERE empresa_id=NEW.empresa_id FOR UPDATE;
  IF NEW.max_colaboradores_ativos IS NOT NULL AND NEW.max_colaboradores_ativos<greatest(real_use,coalesce(stored_use,0)) THEN
   RAISE EXCEPTION 'Limit below current active usage' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION engmarq_private.guard_diagnostico_write() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.empresa_id IS DISTINCT FROM OLD.empresa_id THEN
  RAISE EXCEPTION 'Immutable diagnostic tenant' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.id=NEW.informado_por AND p.empresa_id=NEW.empresa_id AND p.role<>'admin') THEN
  RAISE EXCEPTION 'Diagnostic author must belong to tenant' USING ERRCODE='23514';
 END IF;
 IF current_setting('role',true)='authenticated' THEN
  IF NEW.informado_por IS DISTINCT FROM auth.uid() OR NOT engmarq_private.can_manage_profile(NEW.empresa_id) THEN
   RAISE EXCEPTION 'Diagnostic write denied' USING ERRCODE='42501';
  END IF;
  NEW.informado_em:=clock_timestamp();
 END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION engmarq_private.audit_commercial_write() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE company uuid; old_data jsonb; new_data jsonb;
BEGIN
 IF TG_TABLE_NAME='empresas' THEN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  company:=NEW.id; old_data:=jsonb_build_object('status',OLD.status); new_data:=jsonb_build_object('status',NEW.status);
 ELSE
  company:=NEW.empresa_id;
  IF TG_OP='UPDATE' THEN old_data:=to_jsonb(OLD); END IF;
  new_data:=to_jsonb(NEW);
  IF old_data IS NOT DISTINCT FROM new_data THEN RETURN NEW; END IF;
 END IF;
 INSERT INTO public.auditoria_comercial(empresa_id,objeto,operacao,feature_key,anterior,novo,ator_id,executor)
 VALUES(company,CASE WHEN TG_TABLE_NAME='empresas' THEN 'empresa_status' ELSE TG_TABLE_NAME END,TG_OP,
  CASE WHEN TG_TABLE_NAME='empresa_features' THEN new_data->>'feature_key' END,old_data,new_data,auth.uid(),
  coalesce(nullif(current_setting('role',true),'none'),session_user));
 RETURN NEW;
END $$;
CREATE FUNCTION engmarq_private.deny_audit_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION 'Commercial audit is append-only' USING ERRCODE='42501'; END $$;
REVOKE ALL ON FUNCTION engmarq_private.guard_commercial_write(),engmarq_private.guard_diagnostico_write(),
 engmarq_private.audit_commercial_write(),engmarq_private.deny_audit_mutation() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER guard_commercial_write BEFORE INSERT OR UPDATE ON public.empresa_comercial
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_commercial_write();
CREATE TRIGGER guard_commercial_write BEFORE INSERT OR UPDATE ON public.empresa_features
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_commercial_write();
CREATE TRIGGER guard_commercial_write BEFORE INSERT OR UPDATE ON public.empresa_limites
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_commercial_write();
CREATE TRIGGER guard_diagnostico_write BEFORE INSERT OR UPDATE ON public.empresa_diagnostico_sst
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.guard_diagnostico_write();
CREATE TRIGGER audit_commercial_write AFTER INSERT OR UPDATE ON public.empresa_comercial
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.audit_commercial_write();
CREATE TRIGGER audit_commercial_write AFTER INSERT OR UPDATE ON public.empresa_features
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.audit_commercial_write();
CREATE TRIGGER audit_commercial_write AFTER INSERT OR UPDATE ON public.empresa_limites
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.audit_commercial_write();
CREATE TRIGGER audit_company_status AFTER UPDATE ON public.empresas
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.audit_commercial_write();
CREATE TRIGGER deny_audit_mutation BEFORE UPDATE OR DELETE ON public.auditoria_comercial
 FOR EACH ROW EXECUTE FUNCTION engmarq_private.deny_audit_mutation();
CREATE TRIGGER deny_audit_truncate BEFORE TRUNCATE ON public.auditoria_comercial
 EXECUTE FUNCTION engmarq_private.deny_audit_mutation();

DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['features','empresa_comercial','empresa_features','empresa_limites','empresa_uso','empresa_diagnostico_sst','auditoria_comercial'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  -- Remove default grants too; service_role privileges here are explicitly enumerated below.
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;
ALTER TABLE engmarq_private.onboarding_solicitacoes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON engmarq_private.onboarding_solicitacoes FROM PUBLIC,anon,authenticated,service_role;
-- No client/service provisioning grants in 024. Migration owner is the sole persistence operator.
CREATE POLICY features_read ON public.features FOR SELECT TO authenticated
 USING(engmarq_private.can_read_foundation(public.get_user_empresa_id()));
CREATE POLICY empresa_comercial_read ON public.empresa_comercial FOR SELECT TO authenticated USING(engmarq_private.can_read_foundation(empresa_id));
CREATE POLICY empresa_features_read ON public.empresa_features FOR SELECT TO authenticated USING(engmarq_private.can_read_foundation(empresa_id));
CREATE POLICY empresa_limites_read ON public.empresa_limites FOR SELECT TO authenticated USING(engmarq_private.can_read_foundation(empresa_id));
CREATE POLICY empresa_uso_read ON public.empresa_uso FOR SELECT TO authenticated USING(engmarq_private.can_read_foundation(empresa_id));
CREATE POLICY diagnostico_read ON public.empresa_diagnostico_sst FOR SELECT TO authenticated USING(engmarq_private.can_read_foundation(empresa_id));
CREATE POLICY auditoria_read ON public.auditoria_comercial FOR SELECT TO authenticated USING(engmarq_private.is_commercial_admin());
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['empresa_comercial','empresa_features','empresa_limites'] LOOP
  EXECUTE format('CREATE POLICY commercial_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(engmarq_private.is_commercial_admin())',t);
  EXECUTE format('CREATE POLICY commercial_update ON public.%I FOR UPDATE TO authenticated USING(engmarq_private.is_commercial_admin()) WITH CHECK(engmarq_private.is_commercial_admin())',t);
 END LOOP;
END $$;
CREATE POLICY diagnostico_insert ON public.empresa_diagnostico_sst FOR INSERT TO authenticated
 WITH CHECK(engmarq_private.can_manage_profile(empresa_id) AND informado_por=auth.uid());
CREATE POLICY diagnostico_update ON public.empresa_diagnostico_sst FOR UPDATE TO authenticated
 USING(engmarq_private.can_manage_profile(empresa_id)) WITH CHECK(engmarq_private.can_manage_profile(empresa_id) AND informado_por=auth.uid());
GRANT SELECT ON public.features,public.empresa_comercial,public.empresa_features,public.empresa_limites,
 public.empresa_uso,public.empresa_diagnostico_sst,public.auditoria_comercial TO authenticated;
GRANT INSERT(empresa_id,origem,plano_comercial_id,titularidade,verificado_por,verificado_em),
 UPDATE(plano_comercial_id,titularidade,verificado_por,verificado_em) ON public.empresa_comercial TO authenticated;
GRANT INSERT(empresa_id,feature_key,enabled),UPDATE(enabled) ON public.empresa_features TO authenticated;
GRANT INSERT(empresa_id,max_colaboradores_ativos,ilimitado),UPDATE(max_colaboradores_ativos,ilimitado) ON public.empresa_limites TO authenticated;
GRANT INSERT(empresa_id,possui_pgr,possui_pcmso,possui_treinamentos,programas_documentos_em_dia,treinamentos_em_dia,
 quantidade_aproximada_colaboradores,conhece_grau_risco,grau_risco_informado,schema_version,informado_por),
 UPDATE(possui_pgr,possui_pcmso,possui_treinamentos,programas_documentos_em_dia,treinamentos_em_dia,
 quantidade_aproximada_colaboradores,conhece_grau_risco,grau_risco_informado,schema_version,informado_por)
 ON public.empresa_diagnostico_sst TO authenticated;
-- Trusted counter infrastructure only. No SELECT operational grants are added to Admin.
GRANT SELECT,INSERT,UPDATE ON public.empresa_uso TO service_role;
COMMIT;
